sys_script_email.script:
// Role: one email script for the four notifications. It picks the right text from the event that triggered it.
(function runMailScript(current, template, email, email_action, event) {
  var notify = new CPMNotify();
  var name = event.name + '';
  if (name == 'x_1929776_compli_0.owner.digest') template.print(notify.ownerDigest(event.parm1 + '', event.parm2 + ''));
  else if (name == 'x_1929776_compli_0.evidence.approved') template.print(notify.approval(current));
  else if (name == 'x_1929776_compli_0.evidence.rejected') template.print(notify.rejection(current));
  else if (name == 'x_1929776_compli_0.evidence.submitted') template.print(notify.submitted(current));
})(current, template, email, email_action, event);
